package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator.IdKey;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializerFactory;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.deser.impl.StdDeserializerFactory;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.ser.impl.StdSerializerFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Map.Entry;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DefaultDeserializationContext_findObjectId_TriageGen2Test {

    private DeserializerFactory factory;
    private DefaultDeserializationContext context;

    // Mocking helper classes since they are abstract or complex
    private ObjectIdGenerator<Object> mockGen;
    private ObjectIdResolver mockResolverType;
    private ObjectIdResolver mockExistingResolver;

    @Before
    public void setUp() {
        factory = new StdDeserializerFactory();
        // Using the protected constructor via a subclass or reflection is tricky, 
        // but since we are testing the logic of the method, we use a spy or a mock if possible.
        // However, DefaultDeserializationContext is a concrete class in Jackson.
        // We will use a mock to simulate the behavior of the context if possible, 
        // but since the method is NOT abstract, we need a real instance.

        // Since the constructor is protected, we create a minimal implementation for testing.
        context = new TestableDefaultDeserializationContext(factory, new com.fasterxml.jackson.databind.deser.impl.StdDeserializerCache());

        mockGen = mock(ObjectIdGenerator.class);
        mockResolverType = mock(ObjectIdResolver.class);
        mockExistingResolver = mock(ObjectIdResolver.class);
    }

    /**
     * Minimal implementation to access the protected constructor.
     */
    private static class TestableDefaultDeserializationContext extends DefaultDeserializationContext {
        protected TestableDefaultDeserializationContext(DeserializerFactory df, com.fasterxml.jackson.databind.deser.impl.StdDeserializerCache cache) {
            super(df, cache);
        }

        @Override
        public DefaultDeserializationContext createInstance(DeserializationConfig config, com.fasterxml.jackson.core.JsonParser jp, com.fasterxml.jackson.databind.InjectableValues values) {
            return this;
        }

        @Override
        public DefaultDeserializationContext with(DeserializerFactory factory) {
            return this;
        }
    }

    @Test
    public void testFindObjectId_FirstTime_CreatesNewEntry() {
        Object id = "id1";
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(id)).thenReturn(key);
        when(mockResolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        ReadableObjectId result = context.findObjectId(id, mockGen, mockResolverType);

        assertNotNull(result);
        // In a real scenario, we'd check if the key is set correctly inside ReadableObjectId
    }

    @Test
    public void testFindObjectId_SecondTime_ReturnsCachedEntry() {
        Object id = "id1";
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(id)).thenReturn(key);
        when(mockResolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        ReadableObjectId firstResult = context.findObjectId(id, mockGen, mockResolverType);
        ReadableObjectId secondResult = context.findObjectId(id, mockGen, mockResolverType);

        assertSame("Should return the same instance from the map", firstResult, secondResult);
        verify(mockResolverType, times(1)).newForDeserialization(any());
    }

    @Test
    public void testFindObjectId_WithExistingResolver() {
        Object id = "id1";
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(id)).thenReturn(key);

        // Setup: First call to populate _objectIdResolvers
        when(mockResolverType.newForDeserialization(any())).thenReturn(mockExistingResolver);
        context.findObjectId(id, mockGen, mockResolverType);

        // Second call with a different resolverType that the existing one can handle
        Object id2 = "id2";
        ObjectIdGenerator.IdKey key2 = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(id2)).thenReturn(key2);

        ObjectIdResolver newResolverType = mock(ObjectIdResolver.class);
        when(mockExistingResolver.canUseFor(newResolverType)).thenReturn(true);

        ReadableObjectId result = context.findObjectId(id2, mockGen, newResolverType);

        assertNotNull(result);
        // Verify that the resolver used is the existing one, not a new one from newResolverType
        // Since we can't easily access 'resolver' field in ReadableObjectId without reflection, 
        // we verify that newForDeserialization was not called again.
        verify(newResolverType, never()).newForDeserialization(any());
    }

    @Test
    public void testFindObjectId_WithExistingResolver_CannotUse() {
        Object id = "id1";
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(id)).thenReturn(key);

        // Force create an existing resolver
        when(mockResolverType.newForDeserialization(any())).thenReturn(mockExistingResolver);
        context.findObjectId(id, mockGen, mockResolverType);

        // New resolver type that the existing one cannot handle
        ObjectIdResolver incompatibleType = mock(ObjectIdResolver.class);
        when(mockExistingResolver.canUseFor(incompatibleType)).thenReturn(false);
        when(incompatibleType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        Object id2 = "id2";
        ObjectIdGenerator.IdKey key2 = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(id2)).thenReturn(key2);

        ReadableObjectId result = context.findObjectId(id2, mockGen, incompatibleType);

        assertNotNull(result);
        verify(incompatibleType, times(1)).newForDeserialization(any());
    }

    @Test
    public void testFindObjectId_NullId() {
        // Testing the [databind#742] requirement: allow null
        Object id = null;
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);
        when(mockGen.key(null)).thenReturn(key);
        when(mockResolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        ReadableObjectId result = context.findObjectId(null, mockGen, mockResolverType);

        assertNotNull(result);
    }
}
